package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	var input string
	fmt.Scanln(&input)
	n, _ := strconv.Atoi(strings.TrimSpace(input))
	if n == 1 {
		fmt.Println(n)
	} else if n == 2 {
		fmt.Println(n)
	} else {
		fmt.Println(1)
	}
}

